// Escribir números con marca
console.log(0x10, 0b10, 0xFF);                 // 16 2 255

// De número a texto hexadecimal (y en mayúsculas)
console.log((255).toString(16));               // "ff"
console.log((165).toString(16).toUpperCase()); // "A5"
console.log((7).toString(16).padStart(2, "0")); // "07"

// De texto hexadecimal a número
console.log(parseInt("D3A5", 16));             // 54181

// Las tres partes de un color #F5A524
const c = "F5A524";
console.log(parseInt(c.slice(0, 2), 16),
            parseInt(c.slice(2, 4), 16),
            parseInt(c.slice(4, 6), 16));        // 245 165 36
